use super::fault::*;
use super::{CallingError, HandlingError};
use crate::abort;
#[cfg(feature = "storage")]
use crate::storage::*;
use crate::sys::{SysErr, SyscallErrorCode, SyscallNo};
use crate::xdr::*;
use core::error::Error;
use core::fmt::{self, Display};
use thiserror::Error;

/// An exception generated by SDK internals.
///
#[derive(Debug, Clone, PartialEq, ReadXDR, WriteXDR)]
#[cfg_attr(feature = "debugging", derive(Error))]
#[repr(i32)]
#[non_exhaustive]
pub enum LibraryExn {
    #[cfg_attr(feature = "debugging", error(transparent))]
    Syscall(SyscallExn),

    #[cfg_attr(feature = "debugging", error("Handling a contract call"))]
    Handling(HandlingError),

    #[cfg_attr(feature = "debugging", error("Making a contract call"))]
    Calling(CallingError),

    #[cfg_attr(feature = "debugging", error("Called contract reverted"))]
    Called(#[cfg_attr(feature = "debugging", source)] FaultString),

    #[cfg_attr(feature = "debugging", error("Panic"))]
    Panic(#[cfg_attr(feature = "debugging", source)] crate::Panic),

    #[cfg_attr(
        feature = "debugging",
        error("bytestring_get_sized: expected {expected}, found {found}")
    )]
    BytestringWrongSize { expected: u32, found: u32 },

    #[cfg_attr(feature = "debugging", error("non-negative int underflow"))]
    NonNegativeIntUnderflow,

    #[cfg_attr(feature = "debugging", error("non-negative int overflow"))]
    NonNegativeIntOverflow,

    #[cfg(feature = "storage")]
    #[cfg_attr(feature = "debugging", error("non-negative int overflow"))]
    Storage(StorageError),
}

impl From<HandlingError> for LibraryExn {
    fn from(e: HandlingError) -> Self {
        Self::Handling(e)
    }
}

impl From<CallingError> for LibraryExn {
    fn from(e: CallingError) -> Self {
        Self::Calling(e)
    }
}

#[cfg(feature = "storage")]
impl From<StorageError> for LibraryExn {
    fn from(e: StorageError) -> Self {
        Self::Storage(e)
    }
}

impl LibraryExn {
    pub fn as_syscall_exn(&self) -> Option<&SyscallExn> {
        if let LibraryExn::Syscall(se) = self {
            Some(se)
        } else {
            None
        }
    }
}

#[track_caller]
pub fn library_abort<E: Into<LibraryExn>>(e: E) -> ! {
    let exn: LibraryExn = e.into();

    abort(&exn);
}

/// Abort the contract because a syscall produced an error.
///
#[track_caller]
pub fn syscall_abort2(callno: SyscallNo, errno: SysErr) -> ! {
    abort(&syscall_exn(callno, errno))
}

pub use syscall_abort2 as syscall_abort;

pub fn syscall_exn(callno: SyscallNo, errno: SysErr) -> LibraryExn {
    LibraryExn::Syscall(SyscallExn::new(callno, errno))
}

#[track_caller]
pub fn nnint_overflow() -> ! {
    abort(&LibraryExn::NonNegativeIntOverflow)
}

#[track_caller]
pub fn nnint_underflow() -> ! {
    abort(&LibraryExn::NonNegativeIntUnderflow)
}

#[track_caller]
pub fn decoding_args_abort<E: Error>(e: E) -> ! {
    library_abort(HandlingError::DecodingArgs(FaultString::from_display(e)))
}

#[track_caller]
pub fn encoding_success_abort<E: Error>(e: E) -> ! {
    library_abort(HandlingError::EncodingSuccess(FaultString::from_display(e)))
}

#[track_caller]
pub fn encoding_abort_abort<E: Error>(e: E) -> ! {
    library_abort(HandlingError::EncodingAbort(FaultString::from_display(e)))
}

#[derive(Debug, Clone, Copy, Error, ReadXDR, WriteXDR, PartialEq)]
pub struct SyscallExn {
    callno: SyscallNo,
    errno: SysErr,
}

impl SyscallExn {
    pub fn new(callno: SyscallNo, errno: SysErr) -> Self {
        Self { callno, errno }
    }

    pub fn callno(&self) -> SyscallNo {
        self.callno
    }

    pub fn has_code(&self, err_code: SyscallErrorCode) -> bool {
        self.errno.is_code(err_code)
    }

    pub fn is(&self, call_no: SyscallNo, err_code: SyscallErrorCode) -> bool {
        self.callno == call_no && self.errno == err_code.into()
    }
}

impl Display for SyscallExn {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "Syscall {:?} failed with {}", self.callno, self.errno)
    }
}
